/* Forever Companion — neoficiální komunitní pomůcka. Stav pravidel: 18. 10. 2026. */
(() => {
'use strict';
const KEY='forever-companion-v1';
const RELEASE=new Date('2026-11-05T00:00:00+01:00');
const RAID_DATE='9. 12. 2026';
const RACES=['Orc','Tauren','Troll','Undead','Skyborne'];
const ROLE_LABEL={tank:'Tank',heal:'Healer',melee:'Melee DPS',ranged:'Ranged DPS'};
const CLASSES={
 druid:{name:'Druid',letter:'D',races:['Tauren','Skyborne'],roles:['tank','heal','melee','ranged'],specs:['Balance','Feral','Restoration'],recommended:'Tauren',short:'Všechny čtyři role, nejuniverzálnější volba.',change:'Ve formách může používat více předmětů; Omen of Clarity je základní schopnost od 20, Revive od 12 a Lacerate od 42.',tip:'Dobrá hlavní postava: Feral pro sólo hraní, druhý build na Restoration či tankování. Pro obě role si schovávej oddělenou výbavu.'},
 paladin:{name:'Paladin',letter:'P',races:['Undead'],roles:['tank','heal','melee'],specs:['Holy','Protection','Retribution'],recommended:'Undead',short:'Tank, healer a melee DPS v jedné class.',change:'Nově dostupný pro Undead. Judgement nespotřebovává aktivní Seal; Protection získává úpravy threatu a přežití.',tip:'Praktická alternativa k Druidovi: tank + healer, případně Retribution na questy. Měj dvě sady výbavy.'},
 shaman:{name:'Shaman',letter:'S',races:['Orc','Tauren','Troll','Skyborne'],roles:['heal','melee','ranged'],specs:['Elemental','Enhancement','Restoration'],recommended:'Troll',short:'Healer, melee a ranged DPS, bez klasického tank buildu.',change:'Úpravy totemů a talentů oproti původnímu Classicu; detaily sleduj podle nových beta patch notes.',tip:'Pokud tě baví healing a podpora skupiny, Restoration je přirozená volba. Druhý build Elemental nebo Enhancement.'},
 warrior:{name:'Warrior',letter:'W',races:RACES,roles:['tank','melee'],specs:['Arms','Fury','Protection'],recommended:'Orc',short:'Tank a melee DPS.',change:'Class prochází změnami talentů; ověř konkrétní build podle aktuálních beta změn.',tip:'Připrav si vybavení pro tank i DPS a průběžně zvyšuj weapon skill.'},
 priest:{name:'Priest',letter:'Pr',races:['Troll','Undead'],roles:['heal','ranged'],specs:['Discipline','Holy','Shadow'],recommended:'Undead',short:'Healer a ranged DPS.',change:'Talenty a schopnosti se upravují; přesné priority statů závisí na finální verzi.',tip:'Silná volba pro healing, ale bez tankování. Shadow je cesta pro vlastní questování.'},
 rogue:{name:'Rogue',letter:'R',races:['Orc','Troll','Undead','Skyborne'],roles:['melee'],specs:['Assassination','Combat','Subtlety'],recommended:'Undead',short:'Melee DPS a stealth.',change:'Beta úpravy talentů mohou ovlivnit finální build.',tip:'Specifická alternativa pro PvP nebo stealth hraní.'},
 hunter:{name:'Hunter',letter:'H',races:['Orc','Tauren','Troll','Skyborne'],roles:['ranged'],specs:['Beast Mastery','Marksmanship','Survival'],recommended:'Troll',short:'Ranged DPS a pet.',change:'Class změny míří na známý Classic styl a nové možnosti talentů.',tip:'Pohodlný leveling, při plánování počítej s péčí o peta.'},
 mage:{name:'Mage',letter:'M',races:['Orc','Troll','Undead'],roles:['ranged'],specs:['Arcane','Fire','Frost'],recommended:'Undead',short:'Ranged DPS a silná užitkovost.',change:'Při výběru talentů se řiď beta buildem, ne slepě starými Classic návody.',tip:'Vhodná class pro farmaření, portály a ranged DPS.'},
 warlock:{name:'Warlock',letter:'Wl',races:['Orc','Troll','Undead'],roles:['ranged'],specs:['Affliction','Demonology','Destruction'],recommended:'Orc',short:'Ranged DPS s démony.',change:'Talenty a utility procházejí beta úpravami.',tip:'Připrav si makra pro peta a počítej s hospodařením se soul shardy.'}
};
const CLASS_ORDER=['druid','paladin','shaman','warrior','priest','rogue','hunter','mage','warlock'];
const PROFESSIONS=['','Alchemy','Blacksmithing','Enchanting','Engineering','Leatherworking','Tailoring','Herbalism','Mining','Skinning'];
const CATS=[['class','Classy'],['profession','Profese'],['pvp','PvP'],['adventure','Dobrodružství'],['dungeon','Dungeony'],['raid','Raidy']];
const CHALLENGES=[];
CLASS_ORDER.forEach(k=>[25,45,60].forEach(lvl=>CHALLENGES.push({id:`class-${k}-${lvl}`,cat:'class',title:`${CLASSES[k].name} – level ${lvl}`,detail:'Dosáhni požadované úrovně se svou postavou této classy.',cls:k,lvl})));
['Alchemy','Blacksmithing','Enchanting','Engineering','Leatherworking','Tailoring'].forEach(prof=>[150,225,300].forEach(skill=>CHALLENGES.push({id:`prof-${prof}-${skill}`,cat:'profession',title:`${prof} – skill ${skill}`,detail:'Výrobní profese; sběrné profese se do této skupiny nepočítají.'})));
[3,7,10,13,14].forEach(rank=>CHALLENGES.push({id:`pvp-rank-${rank}`,cat:'pvp',title:`PvP rank ${rank}`,detail:'Dosáhni ranku v systému PvP.'}));
['Warsong Outriders','The Defilers','Frostwolf Clan','Čtvrtá BG reputace'].forEach((name,i)=>CHALLENGES.push({id:`pvp-rep-${i}`,cat:'pvp',title:`Exalted – ${name}`,detail:i===3?'Čtvrtou reputaci upřesníme podle finálního klienta.':'Hordská battleground reputace.'}));
[4,7,10].forEach(week=>CHALLENGES.push({id:`pvp-week-${week}`,cat:'pvp',title:`Field of Honor – týden ${week}`,detail:'Dokonči úkol příslušného týdne PvP Season’s Journey.'}));
CHALLENGES.push({id:'adv-map',cat:'adventure',title:'Prozkoumej celou mapu',detail:'Explore the entire world map na jedné postavě.'},{id:'adv-valthalak',cat:'adventure',title:'Lord Valthalak questline',detail:'Dokonči související dungeon set questline.'});
[[15,25],[26,45],[46,60]].forEach(([a,b])=>CHALLENGES.push({id:`dun-${a}-${b}`,cat:'dungeon',title:`Finální bossové dungeonů ${a}–${b}`,detail:'Poraz finální bossy všech dungeonů daného levelového pásma.'}));
CHALLENGES.push({id:'raid-onyxia',cat:'raid',title:'Onyxia',detail:'Poraz Onyxii.'},{id:'raid-hyjal',cat:'raid',title:'Hyjal Summit – 13 bossů',detail:'Poraz všech 13 bossů.'},{id:'raid-barrow',cat:'raid',title:'Barrow Deeps – 8 bossů',detail:'Poraz všech 8 bossů.'});
if(CHALLENGES.length!==65)throw new Error('Legacy tracker musí mít přesně 65 výzev');
function id(){return 'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
function blank(){return {version:2,characters:[],activeId:null,legacyDone:[],events:[],builds:[],tasks:[{id:'start-class',title:'Vybrat a založit první postavu',done:false},{id:'start-prof',title:'Rozhodnout hlavní dvě profese',done:false},{id:'start-change',title:'Prostudovat změny své classy',done:false}]}}
function load(){try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&Array.isArray(v.characters)&&Array.isArray(v.legacyDone)&&Array.isArray(v.tasks))return {...blank(),...v,events:Array.isArray(v.events)?v.events:[],builds:Array.isArray(v.builds)?v.builds:[]}}catch(_e){}return blank()}
let state=load(),tab='home',category='all',legacyFilter='open',guideClass='druid',toastTimer,diaryPane='events',diaryCharId=null,selectedBuildId=null;
const app=document.querySelector('#app');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(_e){notify('Nelze ukládat data. Zkontroluj nastavení prohlížeče.')}}
function e(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600)}
function active(){return state.characters.find(c=>c.id===state.activeId)||state.characters[0]||null}
function isAuto(ch){return ch.cat==='class'&&state.characters.some(c=>c.cls===ch.cls&&Number(c.level)>=ch.lvl)}
function isDone(ch){return state.legacyDone.includes(ch.id)||isAuto(ch)}
function legacyCount(){return CHALLENGES.filter(isDone).length}
function rolePills(roles){return roles.filter(Boolean).map(r=>`<span class="role-pill ${r==='ranged'||r==='melee'?'dps':r}">${e(ROLE_LABEL[r]||r)}</span>`).join('')}
function classIcon(cls){const c=CLASSES[cls]||CLASSES.druid;return `<div class="class-glyph ${e(cls)}" aria-hidden="true">${e(c.letter)}</div>`}
function button(text,action,cls='secondary'){return `<button class="button ${cls}" type="button" data-action="${e(action)}">${e(text)}</button>`}
function heading(eyebrow,title,desc=''){return `<div class="page-head"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1>${desc?`<p>${e(desc)}</p>`:''}</div></div>`}
function charHtml(c){const cls=CLASSES[c.cls]||CLASSES.druid;return `<article class="card"><div class="char-card">${classIcon(c.cls)}<div class="char-body"><div class="char-top"><strong class="char-name">${e(c.name||'Moje postava')}</strong><span class="tag">LVL ${Number(c.level)||1}</span></div><div class="char-meta">${e(c.race)} · ${e(cls.name)} ${state.activeId===c.id?'<span style="color:var(--gold)">· Aktivní</span>':''}</div><div class="role-pills">${rolePills([c.role,c.role2])}</div><div class="progress"><b style="width:${Math.min(100,Number(c.level)/60*100)}%"></b></div><div class="action-row"><button class="button sm secondary" data-action="select-char" data-id="${e(c.id)}">${state.activeId===c.id?'Vybraná':'Zvolit aktivní'}</button><button class="button sm secondary" data-action="open-diary" data-id="${e(c.id)}">Deník →</button><button class="button sm ghost" data-action="edit-char" data-id="${e(c.id)}">Upravit</button></div></div></div></article>`}
function remaining(){const n=RELEASE.getTime()-Date.now();if(n<=0)return 'Hra už vyšla';const days=Math.floor(n/864e5),hours=Math.floor(n%864e5/36e5);return `${days} dní ${hours} h`}
function suggestions(c){let results=[];if(!c)return [{title:'Založ hlavní postavu',sub:'Vyber libovolnou z devíti class a vytvoř svou vlastní postavu.',tab:'characters'}];const lvl=+c.level||1,cl=CLASSES[c.cls];
 if(lvl<10)results.push({title:'Level 10 · první talenty',sub:`Začni plánovat build pro ${cl.name}.`,tab:'guide'});
 if(lvl<25)results.push({title:'Level 25 · první Legacy bod',sub:'První běžná příležitost odemknout Legacy systém sdílený na účtu.',tab:'legacy'});
 if(lvl<40)results.push({title:'Level 40 · Dual Specialization',sub:'Připrav druhé talenty a případně druhou sadu výbavy.',tab:'guide'});
 if(lvl<45&&lvl>=25)results.push({title:'Level 45 · další Legacy bod',sub:`Další bod za dosažení levelu 45 s classou ${cl.name}.`,tab:'legacy'});
 if(lvl<60&&lvl>=45)results.push({title:'Level 60 · Legacy bod',sub:'Připrav předraidové cíle a dokonči levelování.',tab:'legacy'});
 if(c.cls==='druid'&&lvl<12)results.push({title:'Druid · Revive na levelu 12',sub:'Nové oživení mimo boj.',tab:'guide'});
 if(c.cls==='druid'&&lvl>=35&&lvl<42)results.push({title:'Druid · Lacerate na levelu 42',sub:'Užitečná nová schopnost pro Bear tankování.',tab:'guide'});
 if(c.role!==c.role2&&c.role2)results.push({title:'Vybavení pro druhou roli',sub:`${ROLE_LABEL[c.role]} + ${ROLE_LABEL[c.role2]}: připrav samostatné předměty a talenty.`,tab:'characters'});
 if(!results.length)results.push({title:'Endgame · raidy, profese, Legacy',sub:'Vybírej další výzvy podle role a herních cílů.',tab:'legacy'});
 return results.slice(0,3)}
function home(){const c=active(),done=legacyCount(),openTasks=state.tasks.filter(t=>!t.done);return `<div class="page"><section class="hero"><div class="eyebrow">AZEROTH ČEKÁ · ZA HORDU</div><h1>Tvá cesta začíná<br><span style="color:var(--gold)">právě tady.</span></h1><p>Postavy, Legacy body a další kroky na jednom místě. Žádný zbytečný grind v tabulkách.</p><div class="countdown"><strong data-countdown>${remaining()}</strong><span>do vydání v ČR<br>5. 11. 2026 · 00:00 SEČ</span></div></section><div class="stats"><div class="stat"><strong>${state.characters.length}</strong><span>Postavy</span></div><div class="stat"><strong>${done}<small style="font-size:15px;color:#a7aaa1"> / 65</small></strong><span>Legacy body</span></div><div class="stat"><strong>${openTasks.length}</strong><span>Úkoly k dokončení</span></div></div><div class="section-label"><h2>Aktivní postava</h2><button class="text-button" data-tab="characters">Spravovat →</button></div>${c?charHtml(c):`<div class="card empty"><div class="empty-symbol">♜</div><h3>Ještě nemáš postavu</h3><p>Vyber si jednu z devíti class Hordy. Žádné postavy nejsou předem založené.</p>${button('Přidat první postavu','new-char','')}</div>`}<div class="section-label"><h2>Co dělat dál</h2></div><div class="stack">${suggestions(c).map((s,i)=>`<div class="card" style="display:flex;align-items:center;gap:12px"><span style="font:22px Georgia,serif;color:var(--gold)">${i+1}</span><div style="flex:1"><strong>${e(s.title)}</strong><p>${e(s.sub)}</p></div><button class="text-button" data-tab="${e(s.tab)}" aria-label="Přejít na ${e(s.tab)}">→</button></div>`).join('')}</div><div class="section-label"><h2>Osobní úkoly</h2></div><div class="card">${taskList()}<form id="addTask" class="input-row" style="margin-top:12px"><input name="title" placeholder="Přidat vlastní úkol…" maxlength="140" required aria-label="Nový úkol"><button class="button sm" type="submit">Přidat</button></form></div><div class="section-label"><h2>Důležité termíny</h2></div>${timeline()}<div class="footer">Neoficiální fanouškovský průvodce. Není propojen s Blizzardem.</div></div>`}
function timeline(){return `<div class="card timeline"><div class="time-item"><div class="date">4. 11. 2026<br><span class="muted small">v USA</span></div><div class="description"><strong>Vydání WoW Forever</strong><br><span class="muted small">V Česku 5. 11. o půlnoci (SEČ).</span></div></div><div class="time-item"><div class="date">${RAID_DATE}</div><div class="description"><strong>Odemknutí prvních raidů</strong><br><span class="muted small">Čas se může upřesnit.</span></div></div></div>`}
function taskList(){if(!state.tasks.length)return '<p>Nemáš žádné úkoly. Přidej si vlastní.</p>';return state.tasks.map(t=>`<div class="task"><input type="checkbox" class="check" data-task="${e(t.id)}" ${t.done?'checked':''} aria-label="${e(t.title)}"><div style="flex:1"><div class="task-title ${t.done?'done':''}">${e(t.title)}</div></div><button class="task-delete" type="button" data-action="delete-task" data-id="${e(t.id)}" title="Odstranit úkol" aria-label="Odstranit úkol">×</button></div>`).join('')}
function characters(){return `<div class="page">${heading('AZEROTH · HORDA','Moje postavy','Sám si zakládáš postavy které chceš hrát. Každá má svůj vlastní deník, talenty a rotace.')}
 <div class="action-row">${button('+ Vytvořit vlastní postavu','new-char','')}</div>
 ${state.characters.length?`<div class="grid2" style="margin-top:18px">${state.characters.map(charHtml).join('')}</div>`:'<div class="card empty" style="margin-top:15px"><div class="empty-symbol">♟</div><h3>Žádné předem vytvořené postavy</h3><p>Začni od nuly. Zvol si classu, rasu, jméno i roli – nic za tebe nezakládám.</p></div>'}
 <div class="section-label"><h2>Všech 9 class Hordy</h2></div>
 <div class="grid2">${CLASS_ORDER.map(key=>{const c=CLASSES[key];return `<div class="card class-select-card"><div class="guide-entry">${classIcon(key)}<div style="min-width:0;flex:1"><h3>${e(c.name)}</h3><div class="role-pills">${rolePills(c.roles)}</div><p style="margin:8px 0 9px">${e(c.specs.join(' · '))}</p><button class="button sm secondary" data-action="class-start" data-class="${e(key)}">Založit vlastní postavu</button></div></div></div>`}).join('')}</div></div>`}
function legacy(){let list=CHALLENGES.filter(ch=>(category==='all'||category===ch.cat)&&(legacyFilter==='all'||(legacyFilter==='done'?isDone(ch):!isDone(ch))));const n=legacyCount();return `<div class="page">${heading('ÚČETNÍ POSTUP','Legacy tracker','65 potvrzených výzev, 6 kategorií a až 16 utratitelných bodů na každé postavě při vydání.')}<div class="card" style="margin-bottom:13px"><div class="card-head"><div><span class="eyebrow">ZÍSKANÉ LEGACY BODY</span><div style="font:40px Georgia,serif;color:var(--gold)">${n} <span style="font-size:18px;color:var(--muted)">/ 65</span></div></div><div class="tag">${Math.min(n,16)} / 16 k využití*</div></div><div class="progress"><b style="width:${n/65*100}%"></b></div><p class="muted-note">*Celkový strop utrácení při vydání je 16 bodů na postavu. Body i výzvy jsou sdílené na účtu; každý char má vlastní perky. Stav výzev zde není synchronizován se hrou.</p></div><div class="filter-row" role="group" aria-label="Filtrovat kategorii"><button class="filter ${category==='all'?'active':''}" data-category="all">Vše · 65</button>${CATS.map(([id,title])=>`<button class="filter ${category===id?'active':''}" data-category="${id}">${e(title)} · ${CHALLENGES.filter(c=>c.cat===id).length}</button>`).join('')}</div><div class="filter-row" role="group" aria-label="Filtrovat stav">${[['open','Nesplněné'],['done','Hotové'],['all','Všechny']].map(([v,label])=>`<button class="filter ${legacyFilter===v?'active':''}" data-status="${v}">${label}</button>`).join('')}</div>${!list.length?'<div class="card empty"><h3>Nic tu není</h3><p>Změň filtr, nebo už máš všechno hotové.</p></div>':`<div class="stack">${list.map(ch=>`<label class="legacy-item ${isDone(ch)?'claimed':''}"><input type="checkbox" class="check" data-legacy="${e(ch.id)}" ${isDone(ch)?'checked':''} ${isAuto(ch)?'disabled title="Automaticky podle zadaného levelu postavy"':''}><div class="legacy-main"><strong>${e(ch.title)}</strong><small>${e(isAuto(ch)?'Splněno dle levelu postavy':ch.detail)}</small></div><span class="tag">+1</span></label>`).join('')}</div>`}<div class="notice">Tracker sleduje 65 oficiálně popsaných výzev. Některé konkrétní názvy (například čtvrtá BG reputace) Blizzard zatím v přehledu výzev neupřesnil. Průběh vyplňuješ ručně.</div></div>`}
function guide(){const c=CLASSES[guideClass];return `<div class="page">${heading('PRŮVODCE PRO ZKUŠENÉ','Co se mění ve Forever','Stručné potvrzené novinky a osobní poznámky. Neber je jako finální raidový BiS nebo hotový talentový build.')}<div class="section-label"><h2>Vyber classu</h2></div><div class="filter-row">${CLASS_ORDER.map(key=>`<button class="filter ${key===guideClass?'active':''}" data-guideclass="${key}">${e(CLASSES[key].name)}</button>`).join('')}</div><div class="card" style="margin-bottom:15px"><div class="guide-entry">${classIcon(guideClass)}<div><h2>${e(c.name)} <span style="color:var(--muted);font:12px system-ui">· ${e(c.races.join(' / '))}</span></h2><div class="role-pills" style="margin:8px 0">${rolePills(c.roles)}</div><p>${e(c.short)}</p></div></div><div class="divider"></div><h3>Na co se připravit</h3><p style="margin:7px 0 15px">${e(c.change)}</p><h3>Doporučení pro tvoje hraní</h3><p style="margin-top:7px">${e(c.tip)}</p><div class="mini-cols"><div class="mini"><strong>Specializace</strong><p>${e(c.specs.join(' · '))}</p></div><div class="mini"><strong>Rasy za Hordu</strong><p>${e(c.races.join(' · '))}</p></div></div></div><div class="section-label"><h2>Nezapomeň</h2></div><div class="guide-grid"><div class="card"><h3>Talenty</h3><p>Od levelu 10, nový důležitý milník na 16 bodech. Přeučení u class trainera.</p></div><div class="card"><h3>Dual Spec</h3><p>Od levelu 40. Hodí se hlavně při střídání tank/heal/DPS.</p></div><div class="card"><h3>Legacy</h3><p>První bod běžně kolem levelu 25, případně za výrobní profesi 150 nebo celou mapu.</p></div><div class="card"><h3>Více postav</h3><p>Class výzvy fungují napříč účtem. Další postavy ti usnadní sběr bodů.</p></div><div class="card"><h3>Level cap</h3><p>Maximální level při vydání je 60. Důraz na cestu i dlouhodobý obsah.</p></div><div class="card"><h3>Beta ≠ finální hra</h3><p>Schopnosti a talenty se stále mění. Pravidla jsou uvedena k 18. 10. 2026.</p></div></div><div class="section-label"><h2>Oficiální zdroje</h2></div><div class="card link-list"><a href="https://worldofwarcraft.blizzard.com/en-us/news/24304075/" target="_blank" rel="noopener noreferrer">Rasy a classy pro Hordu ↗</a><a href="https://worldofwarcraft.blizzard.com/en-us/news/24307383/get-to-know-the-world-of-warcraft-forever-legacy-system" target="_blank" rel="noopener noreferrer">Legacy System – všech 65 výzev ↗</a><a href="https://news.blizzard.com/en-us/article/24301515/world-of-warcraft-forever-class-deep-dives-hunter-and-druid" target="_blank" rel="noopener noreferrer">Oficiální změny Druida ↗</a><a href="https://news.blizzard.com/en-us/article/24302099/world-of-warcraft-forever-class-deep-dives-paladin" target="_blank" rel="noopener noreferrer">Oficiální změny Paladina ↗</a><a href="https://worldofwarcraft.blizzard.com/en-us/news/24303862/world-of-warcraft-forever-whats-next" target="_blank" rel="noopener noreferrer">Vydání a plán obsahu ↗</a></div><div class="footer">Neoficiální aplikace. World of Warcraft a Blizzard jsou ochranné známky jejich vlastníků.</div></div>`}
// Character journal, custom talent rank planner and spec-based action priorities.
const EVENT_TYPES={level:'Nový level',dungeon:'Dungeon',raid:'Raid',loot:'Výbava / loot',profession:'Profese',pvp:'PvP',achievement:'Úspěch',quest:'Quest / příběh',reputation:'Reputace',gold:'Gold / obchod',milestone:'Milník',note:'Poznámka'};
const TALENT_URL_BASE='https://wowforevertierlist.com/talent-calculator/';
// Jména a maxima ranků: veřejně popsaný beta snapshot z 28. 9. 2026.
// Stromy v beta klientu se mění; tento seznam neobsahuje pozice ani prerequisite vazby.
const TALENT_PRESET_RAW={
 paladin:{
  Holy:`Divine Strength|5;Divine Intellect|5;Healing Light|3;Spiritual Focus|2;Improved Seals|3;Unyielding Faith|2;Voice of Truth|1;Reverence|3;Purifying Power|2;Infusion of Light|2;Illumination|5;Divine Favor|1;Divine Precision|3;Holy Shock|1;Consecrated Ground|2;Holy Power|5;Light's Vigil|1`,
  Protection:`Toughness|5;Redoubt|5;Precision|3;Guardian's Favor|2;Anticipation|5;Improved Seal of Fury|1;Improved Righteous Fury|3;Shield Specialization|3;Sacred Duty|2;Swift Judgement|1;One-Handed Weapon Specialization|3;Improved Hammer of Justice|3;Templar's Bulwark|1;Reckoning|5;Iron Creed|5;Holy Shield|1`,
  Retribution:`Deflection|5;Benediction|5;Improved Judgement|2;Holy Conduit|2;Conviction|5;Vindication|3;Sanctified Judgement|3;Seal of Command|1;Pursuit of Justice|2;Eye for an Eye|2;Sacred Arbiter|1;Two-Handed Weapon Specialization|3;Vengeance|3;Repentance|1;Champion of the Light|3;Instrument of Law|2;Twist of Light|1`
 },
 druid:{
  Balance:`Improved Wrath|5;Genesis|5;Moonglow|3;Improved Moonfire|2;Nature's Majesty|2;Nature's Reach|2;Improved Entangling Roots|3;Nature's Splendor|1;Insect Swarm|1;Vengeance|5;Improved Starfire|5;Overgrowth|2;Nature's Grace|1;Eclipse|3;Moonfury|5;Moonkin Form|1`,
  Feral:`Ferocity|5;Heart of the Wild|5;Feral Swiftness|2;Feral Instinct|3;Brutal Impact|2;Thick Hide|3;Savage Fury|2;Feral Charge|1;Sharpened Claws|2;Shredding Attacks|3;Primal Bite|1;Predatory Strikes|3;Blood Frenzy|2;Predatory Instincts|2;Leader of the Pack|1;King of the Jungle|3;Natural Reaction|5;Rend and Tear|5;Berserk|1`,
  Restoration:`Nature's Focus|5;Furor|5;Naturalist|5;Subtlety|3;Natural Shapeshifter|3;Reflection|3;Gift of Nature|5;Gift of the Earthmother|1;Tranquil Spirit|5;Improved Rejuvenation|3;Swiftmend|1;Nature's Swiftness|1;Living Spirit|3;Improved Tranquility|2;Improved Regrowth|5;Wild Growth|1`
 },
 shaman:{
  Elemental:`Convection|5;Concussion|5;Elemental Warding|3;Reverberation|5;Call of Flame|3;Elemental Devastation|3;Elemental Focus|1;Elemental Alacrity|3;Improved Fire Nova|2;Eye of the Storm|3;Call of Thunder|1;Elemental Reach|2;Lightning Overload|3;Earthbound|1;Elemental Fury|5;Lava Burst|1`,
  Enhancement:`Earth's Grasp|2;Thundering Strikes|5;Ancestral Knowledge|5;Guardian Totems|2;Mental Dexterity|3;Improved Ghost Wolf|2;Improved Lightning Shield|3;Elemental Weapons|3;Shamanistic Focus|1;Anticipation|3;Toughness|5;Flurry|5;Stormstrike|1;Spirit Weapons|1;Mental Quickness|2;Improved Stormstrike|2;Maelstrom Weapon|5;Rage of the Farseer|1`,
  Restoration:`Improved Healing Wave|5;Totemic Focus|5;Mindfulness|3;Natural Grace|3;Tidal Focus|5;Improved Reincarnation|2;Ancestral Healing|3;Healing Focus|3;Water Shield|1;Tidal Mastery|5;Restorative Totems|5;Mana Tide Totem|1;Healing Way|3;Nature's Swiftness|1;Purification|5;Riptide|1`
 }
};
const TALENT_PRESETS=Object.fromEntries(Object.entries(TALENT_PRESET_RAW).map(([cls,trees])=>[cls,Object.fromEntries(Object.entries(trees).map(([tree,value])=>[tree,value.split(';').map(x=>{const i=x.lastIndexOf('|');return [x.slice(0,i),Number(x.slice(i+1))]})]))]));

const PRESET_ROTATIONS={
 'paladin:Protection':{single:['Righteous Fury a vhodná Aura před soubojem','Seal of Fury udržovat aktivní','Judgement pro threat / taunt podle potřeby','Holy Shield, pokud je vytalentovaný','Holy Strike na cooldown','Consecration, pokud dovolí mana'],aoe:['Righteous Fury + Seal of Fury','Consecration při skupině nepřátel','Judgement / Holy Strike podle priority','Holy Shield pro obranu, pokud máš talent'],opener:['Zkontroluj buffy a Seal','Pull a Judgement','Holy Strike / Consecration dle počtu nepřátel']},
 'paladin:Retribution':{single:['Udržuj vhodný Seal a Blessing','Judgement na cooldown bez automatického obnovení Sealu','Holy Strike na cooldown','Využij vybrané Retribution talenty a proc efekty'],aoe:['Udržuj Seal a buffy','Consecration podle many','Judgement a útoky podle cooldownů'],opener:['Blessing a Aura před bojem','Zvol Seal pro daného nepřítele','Judgement → Holy Strike']},
 'druid:Feral':{single:["Tiger’s Fury podle energie a cooldownu",'Udržuj Rake, neobnovuj předčasně','Na 5 combo pointů udržuj Rip','Shred zezadu jako hlavní builder','Berserk pokud je vytalentovaný, sladit s cooldowny'],aoe:['Rozhodni o formě a dostupných AoE schopnostech','Udržuj důležité debuffy','Nepřepaluj energii'],opener:['Cat Form a případně Prowl','Rake nebo Shred podle situace',"Tiger’s Fury → combo pointy → Rip"]},
 'shaman:Elemental':{single:['Flame Shock pokud cíl vydrží déle','Lava Burst, pokud je dostupný a vhodný','Lightning Bolt jako výplň','Earth Shock na interrupt nebo doražení','Totemy a mana podle skupiny'],aoe:['Totemy podle situace','Chain Lightning pro více cílů','Kontroluj manu a hrozbu'],opener:['Totemy a pozice','Flame Shock','Lava Burst / Lightning Bolt']}
};
function lines(value){return String(value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,30)}
function localToday(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function diaryPerson(){return state.characters.find(c=>c.id===diaryCharId)||active()}
function charBuilds(c){return state.builds.filter(x=>x.charId===c.id)}
function chosenBuild(c){const all=charBuilds(c);return all.find(x=>x.id===selectedBuildId)||all[0]||null}
function eventDate(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date)))return 'Bez data';const p=date.split('-');return `${p[2]}. ${p[1]}. ${p[0]}`}
function buildBudget(level){return Math.max(0,Math.min(51,(Number(level)||1)-9))}
function spent(b){return (b.talents||[]).reduce((s,x)=>s+Math.max(0,Number(x.rank)||0),0)}
function sumTree(b,tree){return (b.talents||[]).filter(x=>x.tree===tree).reduce((s,x)=>s+Math.max(0,Number(x.rank)||0),0)}
function officialCalc(c){return TALENT_URL_BASE+encodeURIComponent(c.cls)}
function currentRotation(b,kind){return Array.isArray(b?.rotations?.[kind])?b.rotations[kind]:[]}
function diary(){const c=diaryPerson();if(!c)return `<div class="page">${heading('OSOBNÍ HISTORIE','Deník postav','Nejdřív založ postavu, ke které bude deník patřit.')}<div class="card empty"><h3>Deník čeká na postavu</h3><p>Každá postava má vlastní příběh, buildy a rotace.</p>${button('+ Nová postava','new-char','')}</div></div>`;
 const myEvents=state.events.filter(x=>x.charId===c.id).sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.created||'').localeCompare(String(a.created||'')));
 const bs=charBuilds(c),b=chosenBuild(c);
 return `<div class="page">${heading('MŮJ AZEROTH','Deník postavy','Události, talentové buildy a herní priority na jednom místě.')}
 <div class="card journal-profile"><div class="guide-entry">${classIcon(c.cls)}<div style="flex:1"><div class="card-head"><h2>${e(c.name)}</h2><span class="tag">LVL ${e(c.level)}</span></div><p>${e(c.race)} · ${e(CLASSES[c.cls].name)} · ${e(c.prof1||'bez profese')}${c.prof2?' / '+e(c.prof2):''}</p><div class="role-pills">${rolePills([c.role,c.role2])}</div></div></div><label class="field-label" for="diaryCharacter" style="margin-top:14px">Přepnout deník na jinou postavu</label><select class="field" id="diaryCharacter">${state.characters.map(x=>`<option value="${e(x.id)}" ${x.id===c.id?'selected':''}>${e(x.name)} · ${e(CLASSES[x.cls].name)}</option>`).join('')}</select></div>
 <div class="journal-tabs" role="group" aria-label="Sekce deníku">${[['events','Kronika'],['talents','Talenty'],['rotation','Rotace']].map(([k,title])=>`<button type="button" class="journal-tab ${diaryPane===k?'active':''}" data-diarypane="${k}">${title}</button>`).join('')}</div>
 ${diaryPane==='events'?diaryEvents(c,myEvents):diaryPane==='talents'?diaryTalents(c,bs,b):diaryRotations(c,bs,b)}</div>`}
function diaryEvents(c,es){return `<div class="section-label"><h2>Kronika dobrodružství</h2><span class="tag">${es.length} záznamů</span></div><div class="action-row">${button('+ Přidat událost','add-event','')}</div>
 ${es.length?`<div class="journal-timeline">${es.map(x=>`<article class="card diary-event"><div class="journal-dot"></div><div class="event-top"><span class="eyebrow">${e(EVENT_TYPES[x.type]||'Událost')} · ${e(eventDate(x.date))}</span><button class="task-delete" data-action="edit-event" data-id="${e(x.id)}" aria-label="Upravit událost">✎</button><button class="task-delete" data-action="delete-event" data-id="${e(x.id)}" aria-label="Smazat událost">×</button></div><h3>${e(x.title)}</h3>${x.note?`<p class="event-note">${e(x.note)}</p>`:''}</article>`).join('')}</div>`:'<div class="card empty"><h3>Zatím žádné zápisky</h3><p>Zapiš první dungeon, dosažený level nebo zajímavý loot.</p></div>'}`}
function buildNav(bs,b){return `<div class="build-nav">${bs.map(x=>`<button type="button" class="build-chip ${x.id===b?.id?'active':''}" data-build="${e(x.id)}">${e(x.name)}</button>`).join('')}<button type="button" class="build-chip add" data-action="new-build">+ Nový build</button></div>`}
function diaryTalents(c,bs,b){
 let html=`<div class="section-label"><h2>Talentové buildy</h2></div>
 <div class="notice">V aplikaci vedeš vlastní talentový deník: součet bodů a limit hodností. Skutečné stromy, řady, návaznosti a aktuální beta talenty otevřeš přes online kalkulátor pro zvolenou classu. Odkaz na hotový build si uložíš k postavě.</div>${buildNav(bs,b)}`;
 if(!b)return html+`<div class="card empty"><h3>Vytvoř první build</h3><p>Pojmenuj si vlastní build pro libovolnou classu a roli.</p><a class="button secondary" href="${officialCalc(c)}" target="_blank" rel="noopener noreferrer">Online talent calculator pro ${e(CLASSES[c.cls].name)} ↗</a></div>`;
 const specNames=CLASSES[c.cls].specs;
 html+=`<div class="card"><div class="card-head"><div><div class="eyebrow">${e(b.spec)} · ${e(ROLE_LABEL[b.role]||b.role)}</div><h2>${e(b.name)}</h2></div><button class="task-delete" data-action="delete-build" data-id="${e(b.id)}" title="Smazat build">×</button></div>
 <div class="action-row">${button('Upravit build','edit-build','secondary')}${button('Duplikovat','clone-build','secondary')}${button('Vynulovat body','clear-talents','ghost')}</div>
 <div class="talent-points"><strong>${spent(b)} / ${buildBudget(b.targetLevel)}</strong><span>bodů · plánovaný level ${Number(b.targetLevel)||60}</span></div>
 <div class="progress"><b style="width:${buildBudget(b.targetLevel)?Math.min(100,100*spent(b)/buildBudget(b.targetLevel)):0}%"></b></div>
 <div class="talent-tree-summary">${specNames.map(tree=>`<div class="tree-tile"><strong>${e(tree)}</strong><span>${sumTree(b,tree)} bodů</span></div>`).join('')}</div></div>`;
 html+=`<div class="section-label"><h2>Moje talenty</h2></div><div class="action-row">${button('+ Přidat vlastní talent','add-talent','secondary')}</div>`;
 if(b.talents?.length){
   html+='<div class="stack" style="margin-top:15px">';
   specNames.forEach(tree=>{
    const ts=b.talents.filter(x=>x.tree===tree);
    if(!ts.length)return;
    html+=`<div class="card"><h3>${e(tree)} · ${sumTree(b,tree)} bodů</h3>`;
    ts.forEach(t=>{
      html+=`<div class="talent-row"><div class="talent-name"><strong>${e(t.name)}</strong><small>${e(tree)}</small></div><button type="button" class="rank-btn" data-action="talent-minus" data-id="${e(t.id)}" aria-label="Odebrat bod ${e(t.name)}">−</button><span class="rank-count">${Math.max(0,+t.rank||0)} / ${Math.max(1,+t.maxRank||1)}</span><button type="button" class="rank-btn" data-action="talent-plus" data-id="${e(t.id)}" aria-label="Přidat bod ${e(t.name)}">+</button><button type="button" class="task-delete" data-action="delete-talent" data-id="${e(t.id)}" aria-label="Smazat talent">×</button></div>`;
    });
    html+='</div>';
   });
   html+='</div>';
 }else html+='<div class="card empty" style="margin-top:15px"><h3>Bez talentů</h3><p>Načti dostupné názvy z beta seznamu nebo přidej vlastní talenty.</p></div>';
 html+=`<div class="card" style="margin-top:16px"><h3>Aktuální plný talent calculator</h3><p>Externí mřížka talentů s pravidly řad a předpoklady. Pro konkrétní postavu si níže ulož odkaz na svůj online build.</p><a class="button" href="${officialCalc(c)}" target="_blank" rel="noopener noreferrer">Otevřít online calculator ↗</a><div class="divider"></div><label class="field-label">Odkaz na můj online build</label>${b.calcUrl?`<a href="${e(b.calcUrl)}" target="_blank" rel="noopener noreferrer" class="saved-link">${e(b.calcUrl)}</a>`:'<p>Zatím bez odkazu.</p>'}<div class="action-row">${button('Uložit odkaz','link-build','secondary')}</div></div>`;
 return html;
}
function diaryRotations(c,bs,b){
 let html=`<div class="section-label"><h2>Rotace a priority</h2></div>${buildNav(bs,b)}`;
 if(!b)return html+'<div class="card empty"><h3>Nejdřív založ build</h3><p>Každý build má vlastní rotace a poznámky, aby se tank, heal a DPS nemíchaly.</p></div>';
 html+=`<div class="card"><div class="eyebrow">${e(CLASSES[c.cls].name)} · ${e(b.spec)} · ${e(ROLE_LABEL[b.role]||b.role)}</div><h3>${e(b.name)}</h3><div class="action-row">${button('Upravit rotaci','edit-rotation','')}</div><p class="muted-note">Jde o vlastní priority schopností. U tanka/healera záleží pořadí na situaci, nikoliv na pevné DPS rotaci.</p></div>`;
 [['opener','Opener · zahájení boje'],['single','Single target · jeden cíl'],['aoe','AoE · více cílů']].forEach(([kind,title])=>{
 html+=`<div class="section-label"><h2>${title}</h2></div><div class="card">`;
 const arr=currentRotation(b,kind);
 html+=arr.length?`<ol class="rotation-list">${arr.map(x=>`<li>${e(x)}</li>`).join('')}</ol>`:'<p>Ještě nemáš zapsané priority.</p>';
 html+='</div>';
 });
 html+=`<div class="section-label"><h2>Poznámky k buildu</h2></div><div class="card">${b.rotations?.notes?`<p class="event-note">${e(b.rotations.notes)}</p>`:'<p>Sem patří cooldowny, makra, stat priority nebo vlastní postřehy.</p>'}</div><div class="notice">Priority jsou tvoje vlastní poznámky. Aplikace ti je automaticky nevymýšlí a neoznačuje jako ověřenou meta rotaci.</div>`;
 return html;
}
function showEventModal(editId=null){const c=diaryPerson();if(!c)return;const x=state.events.find(x=>x.id===editId)||{type:'note',date:localToday(),title:'',note:''};modal(`<div class="modal-title"><h2>${editId?'Upravit zápisek':'Nová událost'}</h2><button data-action="close-modal" type="button" aria-label="Zavřít">×</button></div><form id="eventForm" data-id="${e(editId||'')}"><input type="hidden" name="charId" value="${e(c.id)}"><label class="field-label">Typ události</label><select name="type" class="field">${Object.entries(EVENT_TYPES).map(([k,title])=>`<option value="${k}" ${x.type===k?'selected':''}>${e(title)}</option>`).join('')}</select><label class="field-label field-gap">Datum</label><input name="date" class="field" type="date" required value="${e(x.date)}"><label class="field-label field-gap">Co se stalo?</label><input name="title" class="field" maxlength="120" placeholder="Například první run Deadmines" required value="${e(x.title)}"><label class="field-label field-gap">Podrobnosti (nepovinné)</label><textarea name="note" class="field area" rows="5" maxlength="3000" placeholder="Získané věci, parta, bossové, poznámky…">${e(x.note)}</textarea><div class="action-row"><button type="submit" class="button">Uložit událost</button>${button('Zrušit','close-modal','secondary')}</div></form>`)}
function showBuildModal(editId=null){const c=diaryPerson();if(!c)return;const x=state.builds.find(x=>x.id===editId)||{name:'',spec:CLASSES[c.cls].specs[0],role:c.role,targetLevel:60};modal(`<div class="modal-title"><h2>${editId?'Upravit build':'Nový talentový build'}</h2><button type="button" data-action="close-modal" aria-label="Zavřít">×</button></div><form id="buildForm" data-id="${e(editId||'')}"><label class="field-label">Název buildu</label><input class="field" required maxlength="70" name="name" value="${e(x.name)}" placeholder="Například Tank do dungeonů"><div class="form-grid" style="margin-top:12px"><div><label class="field-label">Specializace</label><select class="field" name="spec">${selectOptions(CLASSES[c.cls].specs,x.spec)}</select></div><div><label class="field-label">Role</label><select class="field" name="role">${roleOptions(c.cls,x.role)}</select></div><div><label class="field-label">Plánovaný level</label><input class="field" name="targetLevel" inputmode="numeric" type="number" min="1" max="60" required value="${e(x.targetLevel||60)}"></div></div><div class="action-row"><button class="button" type="submit">Uložit build</button>${button('Zrušit','close-modal','secondary')}</div></form>`)}
function showTalentModal(){const c=diaryPerson(),b=c&&chosenBuild(c);if(!b)return;modal(`<div class="modal-title"><h2>Nový talent v buildu</h2><button type="button" data-action="close-modal" aria-label="Zavřít">×</button></div><form id="talentForm"><label class="field-label">Název talentu</label><input class="field" name="name" required maxlength="90" placeholder="Například Redoubt"><div class="form-grid" style="margin-top:12px"><div><label class="field-label">Strom</label><select class="field" name="tree">${selectOptions(CLASSES[c.cls].specs,b.spec)}</select></div><div><label class="field-label">Max. hodnost (1–5)</label><input class="field" name="maxRank" type="number" min="1" max="5" value="5" required></div></div><div class="action-row"><button class="button" type="submit">Přidat talent</button>${button('Zrušit','close-modal','secondary')}</div></form>`)}
function showRotationModal(){const c=diaryPerson(),b=c&&chosenBuild(c);if(!b)return;modal(`<div class="modal-title"><h2>Rotace · ${e(b.name)}</h2><button type="button" data-action="close-modal" aria-label="Zavřít">×</button></div><form id="rotationForm"><p class="muted-note">Každý řádek představuje jeden krok nebo prioritu. Pořadí lze kdykoliv přepsat.</p>${[['opener','Opener'],['single','Single target'],['aoe','AoE']].map(([kind,title])=>`<label class="field-label field-gap">${title}</label><textarea class="field area" name="${kind}" rows="5" maxlength="5000" placeholder="Jeden spell / podmínka na řádek">${e(currentRotation(b,kind).join('\n'))}</textarea>`).join('')}<label class="field-label field-gap">Poznámky</label><textarea class="field area" name="notes" rows="3" maxlength="3000">${e(b.rotations?.notes||'')}</textarea><div class="action-row"><button class="button" type="submit">Uložit rotace</button>${button('Zrušit','close-modal','secondary')}</div></form>`)}
function linkBuildModal(){const c=diaryPerson(),b=c&&chosenBuild(c);if(!b)return;modal(`<div class="modal-title"><h2>Odkaz na online build</h2><button type="button" data-action="close-modal">×</button></div><form id="linkBuildForm"><label class="field-label">URL z aktuálního talent kalkulátoru</label><input class="field" type="url" name="calcUrl" placeholder="https://…" value="${e(b.calcUrl||'')}"><p class="muted-note">Odkaz musí používat https. Prázdné pole odkaz odebere.</p><div class="action-row"><button class="button" type="submit">Uložit odkaz</button>${button('Zrušit','close-modal','secondary')}</div></form>`)}
function settings(){return `<div class="page">${heading('BEZ ÚČTU · BEZ CLOUDU','Moje data','Ukládání probíhá jen v zařízení. Pro přenos mezi telefonem a PC využij zálohu JSON.')}<div class="card"><h3>Záloha a obnova</h3><p>Export obsahuje postavy, deníky, talentové buildy, rotace, úkoly i Legacy výzvy.</p><div class="settings-actions">${button('Stáhnout zálohu JSON','export','')}${button('Nahrát zálohu','import','secondary')}</div><input id="importInput" accept=".json,application/json" type="file" hidden><div class="divider"></div><h3>O aplikaci</h3><p style="margin-top:9px">Forever Companion v2.1 · offline na GitHub Pages po prvním načtení · žádné analytické skripty · žádné přihlašování.</p><div class="notice">Pokud na iPhonu vymažeš data Safari nebo otevřeš aplikaci na jiné doméně, místní postup se nemusí přenést. Pravidelně exportuj zálohu.</div>${button('Vymazat všechna uložená data','reset','danger')}</div><div class="section-label"><h2>Jak nainstalovat na iPhone</h2></div><div class="card"><ol class="simple-list"><li>Nahraj soubory do repozitáře na GitHubu a aktivuj GitHub Pages.</li><li>Otevři adresu webu v Safari na iPhonu.</li><li>V nabídce Sdílet zvol <strong>Přidat na plochu</strong>.</li><li>Po prvním načtení může aplikace fungovat i bez internetu.</li></ol></div></div>`}
function render(){const pages={home,characters,diary,legacy,guide,settings};app.innerHTML=pages[tab]();document.querySelectorAll('#bottomNav button').forEach(b=>{const is=b.dataset.tab===tab;b.classList.toggle('active',is);b.setAttribute('aria-current',is?'page':'false')});}
function navigate(t){if(!['home','characters','diary','legacy','guide','settings'].includes(t))return;tab=t;render();scrollTo({top:0,behavior:'instant'})}
function roleOptions(cls,selected,includeEmpty=false){const opts=(CLASSES[cls]||CLASSES.druid).roles;return (includeEmpty?'<option value="">Žádná</option>':'')+opts.map(r=>`<option value="${r}" ${selected===r?'selected':''}>${ROLE_LABEL[r]}</option>`).join('')}
function selectOptions(values,selected){return values.map(v=>`<option value="${e(v)}" ${selected===v?'selected':''}>${e(v||'—')}</option>`).join('')}
function modal(inner){document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="Editor postavy">${inner}</div></div>`}
function closeModal(){document.querySelector('#modalRoot').innerHTML=''}
function showCharModal(editId=null,clsPreset='',retain=null){
 const existing=state.characters.find(c=>c.id===editId);
 const initial=clsPreset&&CLASSES[clsPreset]?clsPreset:'';
 const data=retain||existing||{name:'',cls:initial,race:initial?CLASSES[initial].races[0]:'',level:1,role:initial?CLASSES[initial].roles[0]:'',role2:'',prof1:'',prof2:''};
 const cls=CLASSES[data.cls]?data.cls:'',def=cls?CLASSES[cls]:null;
 const race=def?(def.races.includes(data.race)?data.race:def.races[0]):'';
 modal(`<div class="modal-title"><h2>${existing?'Upravit postavu':'Vlastní postava'}</h2><button type="button" data-action="close-modal" aria-label="Zavřít">×</button></div>
 <form id="characterForm" data-edit="${e(editId||'')}"><div class="form-grid">
 <div class="full"><label class="field-label" for="charName">Jméno postavy</label><input id="charName" class="field" name="name" maxlength="36" required placeholder="Jméno mé postavy" value="${e(data.name)}"></div>
 <div><label class="field-label" for="charClass">Classa – všech devět</label><select id="charClass" class="field" name="cls" required><option value="" ${!cls?'selected':''} disabled>Vyber classu</option>${CLASS_ORDER.map(k=>`<option value="${k}" ${cls===k?'selected':''}>${e(CLASSES[k].name)}</option>`).join('')}</select></div>
 <div><label class="field-label" for="charRace">Rasa</label><select id="charRace" class="field" name="race" required ${!cls?'disabled':''}>${def?selectOptions(def.races,race):'<option value="">Nejdřív vyber classu</option>'}</select></div>
 <div><label class="field-label" for="charLevel">Level</label><input class="field" id="charLevel" name="level" type="number" min="1" max="60" inputmode="numeric" value="${e(data.level||1)}" required></div>
 <div><label class="field-label" for="charRole">Primární role</label><select class="field" id="charRole" name="role" required ${!cls?'disabled':''}>${def?roleOptions(cls,data.role):'<option value="">Nejdřív vyber classu</option>'}</select></div>
 <div><label class="field-label" for="charRole2">Druhá role</label><select class="field" id="charRole2" name="role2" ${!cls?'disabled':''}>${def?roleOptions(cls,data.role2,true):'<option value="">Nejdřív vyber classu</option>'}</select></div>
 <div><label class="field-label" for="prof1">Profese 1</label><select class="field" name="prof1" id="prof1">${selectOptions(PROFESSIONS,data.prof1)}</select></div>
 <div><label class="field-label" for="prof2">Profese 2</label><select class="field" name="prof2" id="prof2">${selectOptions(PROFESSIONS,data.prof2)}</select></div>
 </div><p class="muted-note" style="margin-top:13px">Vybíráš rasu, classu a role. Deník i buildy se přidají až po uložení postavy. Při změně classy lze ztratit její původní buildy.</p>
 <div class="action-row"><button class="button" type="submit">${existing?'Uložit změny':'Založit postavu'}</button><button class="button secondary" type="button" data-action="close-modal">Zrušit</button>${existing?`<button class="button danger" type="button" data-action="remove-char" data-id="${e(editId)}">Smazat</button>`:''}</div></form>`)
}
function exportData(){const json=JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([json],{type:'application/json'}));a.download='forever-companion-zaloha.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1200);notify('Záloha připravena ke stažení')}
function importData(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{
 const data=JSON.parse(String(reader.result));if(!data||!Array.isArray(data.characters)||!Array.isArray(data.legacyDone)||!Array.isArray(data.tasks))throw Error('Chybný formát');
 if(!confirm('Nahradit stávající postup importovanou zálohou?'))return;
 const safeChars=data.characters.filter(c=>c&&CLASSES[c.cls]).slice(0,100).map(c=>({id:String(c.id||id()).slice(0,70),name:String(c.name||'Moje postava').slice(0,36),cls:c.cls,race:CLASSES[c.cls].races.includes(c.race)?c.race:CLASSES[c.cls].recommended,level:Math.max(1,Math.min(60,+c.level||1)),role:CLASSES[c.cls].roles.includes(c.role)?c.role:CLASSES[c.cls].roles[0],role2:CLASSES[c.cls].roles.includes(c.role2)?c.role2:'',prof1:PROFESSIONS.includes(c.prof1)?c.prof1:'',prof2:PROFESSIONS.includes(c.prof2)?c.prof2:''}));
 const ids=new Set(safeChars.map(c=>c.id));
 const safeEvents=(Array.isArray(data.events)?data.events:[]).filter(x=>x&&ids.has(x.charId)).slice(0,1500).map(x=>({id:String(x.id||id()).slice(0,70),charId:x.charId,type:EVENT_TYPES[x.type]?x.type:'note',date:/^\d{4}-\d{2}-\d{2}$/.test(x.date)?x.date:localToday(),title:String(x.title||'Událost').slice(0,120),note:String(x.note||'').slice(0,3000),created:String(x.created||'').slice(0,40)}));
 const safeBuilds=(Array.isArray(data.builds)?data.builds:[]).filter(x=>x&&ids.has(x.charId)).slice(0,100).map(x=>{const c=safeChars.find(z=>z.id===x.charId);return {id:String(x.id||id()).slice(0,70),charId:x.charId,name:String(x.name||'Build').slice(0,70),spec:CLASSES[c.cls].specs.includes(x.spec)?x.spec:CLASSES[c.cls].specs[0],role:CLASSES[c.cls].roles.includes(x.role)?x.role:CLASSES[c.cls].roles[0],targetLevel:Math.max(1,Math.min(60,Number(x.targetLevel)||60)),talents:(Array.isArray(x.talents)?x.talents:[]).filter(t=>t&&CLASSES[c.cls].specs.includes(t.tree)).slice(0,70).map(t=>({id:String(t.id||id()).slice(0,70),name:String(t.name||'Talent').slice(0,90),tree:t.tree,maxRank:Math.max(1,Math.min(5,+t.maxRank||1)),rank:Math.max(0,Math.min(5,+t.rank||0))})),rotations:{single:lines((x.rotations?.single||[]).join('\n')),aoe:lines((x.rotations?.aoe||[]).join('\n')),opener:lines((x.rotations?.opener||[]).join('\n')),notes:String(x.rotations?.notes||'').slice(0,3000)},calcUrl:/^https:\/\//.test(String(x.calcUrl||''))?String(x.calcUrl).slice(0,2000):''}});
 state={...blank(),characters:safeChars,activeId:ids.has(data.activeId)?data.activeId:safeChars[0]?.id||null,legacyDone:data.legacyDone.filter(x=>CHALLENGES.some(c=>c.id===x)),tasks:data.tasks.filter(t=>t&&typeof t.title==='string').slice(0,250).map(t=>({id:String(t.id||id()).slice(0,70),title:t.title.slice(0,140),done:!!t.done})),events:safeEvents,builds:safeBuilds};
 diaryCharId=null;selectedBuildId=null;save();render();notify('Záloha obnovena');
 }catch(err){console.error(err);notify('Nepodařilo se přečíst zálohu JSON')}};reader.readAsText(file)}
app.addEventListener('click',event=>{const t=event.target.closest('[data-tab],[data-action],[data-category],[data-status],[data-guideclass],[data-diarypane],[data-build]');if(!t)return;
 if(t.dataset.tab){navigate(t.dataset.tab);return}
 if(t.dataset.category){category=t.dataset.category;render();return}
 if(t.dataset.status){legacyFilter=t.dataset.status;render();return}
 if(t.dataset.guideclass){guideClass=t.dataset.guideclass;render();return}
 if(t.dataset.diarypane){diaryPane=t.dataset.diarypane;render();return}
 if(t.dataset.build){selectedBuildId=t.dataset.build;render();return}
 switch(t.dataset.action){
 case 'open-diary':diaryCharId=t.dataset.id;selectedBuildId=null;diaryPane='events';navigate('diary');break;
 case 'add-event':showEventModal();break;
 case 'edit-event':showEventModal(t.dataset.id);break;
 case 'delete-event':if(confirm('Smazat tuto událost?')){state.events=state.events.filter(x=>x.id!==t.dataset.id);save();render()}break;
 case 'new-build':showBuildModal();break;
 case 'edit-build':{const c=diaryPerson();if(c){const b=chosenBuild(c);if(b)showBuildModal(b.id)}break}
 case 'delete-build':if(confirm('Smazat build včetně talentů a rotací?')){state.builds=state.builds.filter(b=>b.id!==t.dataset.id);selectedBuildId=null;save();render()}break;
 case 'clone-build':{const c=diaryPerson();if(!c)break;const b=chosenBuild(c);if(!b)break;const clone=JSON.parse(JSON.stringify(b));clone.id=id();clone.name=clone.name+' – kopie';clone.talents=clone.talents.map(t=>({...t,id:id()}));state.builds.push(clone);selectedBuildId=clone.id;save();render();notify('Build duplikován');break}
 case 'clear-talents':{const c=diaryPerson(),b=c&&chosenBuild(c);if(b&&confirm('Vynulovat všechny přidělené talentové body v tomto buildu?')){b.talents.forEach(t=>t.rank=0);save();render()}break}
 case 'preset-talents':{const c=diaryPerson(),b=c&&chosenBuild(c),trees=c&&TALENT_PRESETS[c.cls];if(!b||!trees)break;const existing=new Set(b.talents.map(t=>t.tree+'::'+t.name));let added=0;Object.entries(trees).forEach(([tree,entries])=>{entries.forEach(([name,maxRank])=>{if(existing.has(tree+'::'+name)||b.talents.length>=70)return;b.talents.push({id:id(),name,tree,maxRank,rank:0});added++})});save();render();notify(added+' talentů načteno ze starší beta verze');break}
 case 'add-talent':showTalentModal();break;
 case 'delete-talent':{const c=diaryPerson(),b=c&&chosenBuild(c);if(b){b.talents=b.talents.filter(x=>x.id!==t.dataset.id);save();render()}break}
 case 'talent-plus':case 'talent-minus':{const c=diaryPerson(),b=c&&chosenBuild(c);if(!b)break;const talent=b.talents.find(x=>x.id===t.dataset.id);if(!talent)break;const delta=t.dataset.action==='talent-plus'?1:-1;if(delta>0&&(spent(b)>=buildBudget(b.targetLevel)||talent.rank>=talent.maxRank)){notify('Není dostupný další talentový bod');break}talent.rank=Math.max(0,Math.min(talent.maxRank,talent.rank+delta));save();render();break}
 case 'edit-rotation':showRotationModal();break;
 case 'link-build':linkBuildModal();break;
 case 'preset-rotation':{const c=diaryPerson(),b=c&&chosenBuild(c);if(!b)break;const preset=PRESET_ROTATIONS[c.cls+':'+b.spec];if(!preset)break;if(Object.values(b.rotations||{}).some(v=>Array.isArray(v)&&v.length)&&!confirm('Přepsat dosavadní rotaci ukázkovými prioritami?'))break;b.rotations={...b.rotations,single:[...preset.single],aoe:[...preset.aoe],opener:[...preset.opener]};save();render();notify('Orientační rotace uložena');break}
 case 'new-char':showCharModal();break;
 case 'class-start':showCharModal(null,t.dataset.class);break;
 case 'edit-char':showCharModal(t.dataset.id);break;
 case 'select-char':state.activeId=t.dataset.id;save();render();notify('Aktivní postava změněna');break;
 case 'delete-task':state.tasks=state.tasks.filter(task=>task.id!==t.dataset.id);save();render();break;
 case 'export':exportData();break;
 case 'import':document.querySelector('#importInput')?.click();break;
 case 'reset':if(confirm('Opravdu trvale smazat všechny postavy, deníky, buildy, rotace, úkoly i Legacy postup z tohoto zařízení?')){state=blank();save();navigate('home');notify('Data vymazána')}break;
 }});
app.addEventListener('change',event=>{const t=event.target;if(t.matches('[data-task]')){const task=state.tasks.find(x=>x.id===t.dataset.task);if(task){task.done=t.checked;save();render()}}if(t.matches('[data-legacy]')){const ch=CHALLENGES.find(c=>c.id===t.dataset.legacy);if(!ch||isAuto(ch))return;state.legacyDone=t.checked?[...new Set([...state.legacyDone,ch.id])]:state.legacyDone.filter(x=>x!==ch.id);save();render()}if(t.matches('#diaryCharacter')){diaryCharId=t.value;selectedBuildId=null;render()}if(t.matches('#importInput')){importData(t.files?.[0]);t.value=''}});
app.addEventListener('submit',event=>{if(event.target.id!=='addTask')return;event.preventDefault();const title=event.target.elements.title.value.trim();if(!title)return;state.tasks.push({id:id(),title:title.slice(0,140),done:false});save();render();notify('Úkol přidán')});
const root=document.querySelector('#modalRoot');
root.addEventListener('click',event=>{if(event.target.classList.contains('modal-backdrop'))closeModal();const t=event.target.closest('[data-action]');if(!t)return;if(t.dataset.action==='close-modal')closeModal();if(t.dataset.action==='remove-char'){if(confirm('Smazat tuto postavu?')){state.characters=state.characters.filter(c=>c.id!==t.dataset.id);state.events=state.events.filter(x=>x.charId!==t.dataset.id);state.builds=state.builds.filter(x=>x.charId!==t.dataset.id);if(state.activeId===t.dataset.id)state.activeId=state.characters[0]?.id||null;save();closeModal();render();notify('Postava odebrána')}}});
root.addEventListener('change',event=>{if(event.target.id!=='charClass')return;const f=document.querySelector('#characterForm');const data=Object.fromEntries(new FormData(f).entries());data.cls=event.target.value;if(!CLASSES[data.cls])return;data.race=CLASSES[data.cls].races[0];data.role=CLASSES[data.cls].roles.includes(data.role)?data.role:CLASSES[data.cls].roles[0];data.role2=CLASSES[data.cls].roles.includes(data.role2)?data.role2:'';showCharModal(f.dataset.edit||null,data.cls,data)});
root.addEventListener('submit',event=>{if(!['eventForm','buildForm','talentForm','rotationForm','linkBuildForm'].includes(event.target.id))return;event.preventDefault();const f=event.target,vals=Object.fromEntries(new FormData(f).entries()),c=diaryPerson();if(!c)return;
 if(f.id==='eventForm'){if(state.events.length>=1500&&!f.dataset.id){notify('Limit 1500 záznamů, vytvoř zálohu');return}const row={id:f.dataset.id||id(),charId:c.id,type:EVENT_TYPES[vals.type]?vals.type:'note',date:vals.date||localToday(),title:String(vals.title||'').trim().slice(0,120),note:String(vals.note||'').slice(0,3000),created:state.events.find(x=>x.id===f.dataset.id)?.created||new Date().toISOString()};if(!row.title)return;state.events=f.dataset.id?state.events.map(x=>x.id===f.dataset.id?row:x):[...state.events,row];}
 else if(f.id==='buildForm'){const lev=Math.max(1,Math.min(60,+vals.targetLevel||60));const old=state.builds.find(x=>x.id===f.dataset.id);if(!old&&state.builds.length>=100){notify('Limit 100 buildů');return}if(old&&spent(old)>buildBudget(lev)){notify('Nejdřív odeber talentové body pro nižší level');return}const row={id:f.dataset.id||id(),charId:c.id,name:String(vals.name||'Build').trim().slice(0,70),spec:CLASSES[c.cls].specs.includes(vals.spec)?vals.spec:CLASSES[c.cls].specs[0],role:CLASSES[c.cls].roles.includes(vals.role)?vals.role:c.role,targetLevel:lev,talents:old?.talents||[],rotations:old?.rotations||{single:[],aoe:[],opener:[],notes:''},calcUrl:old?.calcUrl||''};state.builds=old?state.builds.map(x=>x.id===old.id?row:x):[...state.builds,row];selectedBuildId=row.id;}
 else {const b=chosenBuild(c);if(!b)return;
 if(f.id==='talentForm'){const name=String(vals.name||'').trim().slice(0,90);if(!name||!CLASSES[c.cls].specs.includes(vals.tree))return;if(b.talents.length>=70){notify('Limit 70 talentů v buildu');return}b.talents.push({id:id(),name,tree:vals.tree,maxRank:Math.max(1,Math.min(5,+vals.maxRank||1)),rank:0});}
 if(f.id==='rotationForm'){b.rotations={single:lines(vals.single),aoe:lines(vals.aoe),opener:lines(vals.opener),notes:String(vals.notes||'').slice(0,3000)};}
 if(f.id==='linkBuildForm'){const url=String(vals.calcUrl||'').trim();if(url&&!/^https:\/\/[^\s]+$/i.test(url)){notify('Použij platnou HTTPS adresu');return}b.calcUrl=url.slice(0,2000);}}
 save();closeModal();render();notify('Uloženo');
 });
root.addEventListener('submit',event=>{if(event.target.id!=='characterForm')return;event.preventDefault();const f=event.target,data=Object.fromEntries(new FormData(f).entries());const c=CLASSES[data.cls];if(!c||!c.races.includes(data.race)||!c.roles.includes(data.role)){notify('Zkontroluj classu, rasu a roli');return}const level=Math.min(60,Math.max(1,parseInt(data.level,10)||1));const prof1=PROFESSIONS.includes(data.prof1)?data.prof1:'',prof2=PROFESSIONS.includes(data.prof2)?data.prof2:'';if(prof1&&prof1===prof2){notify('Vyber dvě rozdílné profese');return}const character={id:f.dataset.edit||id(),name:(data.name||'Moje postava').trim().slice(0,36),cls:data.cls,race:data.race,role:data.role,role2:data.role2===data.role?'':(c.roles.includes(data.role2)?data.role2:''),level,prof1,prof2};if(f.dataset.edit){const old=state.characters.find(c=>c.id===f.dataset.edit);if(old?.cls!==character.cls&&state.builds.some(x=>x.charId===character.id)){if(!confirm('Změna classy smaže uložené talentové buildy a rotace této postavy. Pokračovat?'))return;state.builds=state.builds.filter(x=>x.charId!==character.id)}state.characters=state.characters.map(c=>c.id===f.dataset.edit?character:c)}else{state.characters.push(character);state.activeId=character.id}if(!state.activeId)state.activeId=character.id;save();closeModal();render();notify('Postava uložena')});
document.querySelector('#bottomNav').addEventListener('click',event=>{const t=event.target.closest('[data-tab]');if(t)navigate(t.dataset.tab)});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal()});
setInterval(()=>{const el=document.querySelector('[data-countdown]');if(el)el.textContent=remaining()},60000);
render();
if('serviceWorker' in navigator&&location.protocol==='https:'){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}
})();
